mapper.select:
SELECT DISTINCT d.iot_id, p.third_platform, d.product_key, d.device_id, d.ext_device_id, d.device_name, d.product_name, p.photo_url AS product_image, d.coordinate, p.device_node AS device_type, p.device_node, CASE WHEN d.state = 1 THEN 1 ELSE 0 END AS online_status, to_timestamp(d.online_time) AS last_online_time, d.gw_product_key, d.device_tag, d.device_address, d.ext1, d.ext2, d.ext3, d.ext4, to_timestamp(d.create_time) AS create_time, -- 新增：显式查询原始create_time字段（可加别名避免冲突） d.create_time AS raw_create_time FROM iot_device d LEFT JOIN iot_product p ON d.product_key = p.product_key LEFT JOIN iot_device_tags tg ON (tg.iot_id = d.iot_id AND (tg.tag_type = 'devGroup' OR tg.tag_key = 'devGroup')) LEFT JOIN iot_device_group dg ON tg.tag_value = CAST(dg.id AS VARCHAR) WHERE d.application = #{query.linkedAppId}
AND (d.device_name LIKE CONCAT('%', #{query.keyword}, '%') OR d.device_id LIKE CONCAT('%', #{query.keyword}, '%'))
AND d.device_name LIKE CONCAT('%', #{query.deviceName}, '%')
AND d.device_id LIKE CONCAT('%', #{query.deviceId}, '%')
AND p.device_node = #{query.deviceNode}
AND CAST(d.device_tag AS text) LIKE CONCAT('%', #{query.deviceTag}, '%')
AND (dg.group_name LIKE CONCAT('%', #{query.devGroupName}, '%') OR tg.tag_value LIKE CONCAT('%', #{query.devGroupName}, '%'))
AND p.classified_id = #{query.classifiedId}
AND d.product_key = #{query.productKey}
AND d.state = #{query.onlineStatus}
AND d.iot_id IN
#{id}
-- 修正：使用SELECT列表中存在的别名排序（或原始字段别名） ORDER BY raw_create_time DESC

SELECT COUNT(1)
FROM iot_device
WHERE application = #{linkedAppId}
